const raw = $('On Calendly Booking Event').first().json || {};
const cfg = $('Booking Configuration').first().json || {};
const payload = raw.payload || raw;
const qa = Array.isArray(payload.questions_and_answers) ? payload.questions_and_answers : [];
const qaPhone = qa.find((q) => /phone|whatsapp|mobile/i.test(String(q.question || '')))?.answer || '';
const rawPhone = String(payload.text_reminder_number || qaPhone || '').trim();
const cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.length < 8) return [];

const startIso = String(payload.scheduled_event?.start_time || payload.event_start_time || '');
const startMs = Date.parse(startIso);
const pollMs = Number.isFinite(startMs) ? startMs - Number(cfg.pollHoursBefore || 24) * 3600 * 1000 : Date.now();
const finalMs = Number.isFinite(startMs) ? startMs - Number(cfg.finalReminderHoursBefore || 2) * 3600 * 1000 : Date.now();
const eventType = String(raw.event || 'invitee.created');
const bookingId = String(payload.uri || payload.scheduled_event?.uri || cleanPhone).split('/').pop() || cleanPhone;
const joinUrl = String(payload.scheduled_event?.location?.join_url || payload.scheduled_event?.location?.location || 'See calendar invite');

return [{
  json: {
    bookingId,
    eventType,
    isCreated: eventType === 'invitee.created',
    eventName: String(payload.scheduled_event?.name || 'Consultation Call'),
    inviteeName: String(payload.name || payload.first_name || 'there').trim(),
    inviteeEmail: String(payload.email || '').trim(),
    cleanPhone,
    startTimeIso: startIso,
    startTimeFormatted: Number.isFinite(startMs) ? new Date(startMs).toUTCString() : startIso,
    joinUrl,
    rescheduleUrl: String(payload.reschedule_url || cfg.rebookingUrl),
    cancelUrl: String(payload.cancel_url || cfg.rebookingUrl),
    pollDueAt: new Date(pollMs).toISOString(),
    finalReminderDueAt: new Date(finalMs).toISOString(),
    brandName: cfg.brandName,
    rebookingUrl: cfg.rebookingUrl,
    spreadsheetId: cfg.spreadsheetId,
    slackHostChannelId: cfg.slackHostChannelId,
  },
}];

const cfg = $('Sweep Configuration').first().json || {};
const now = Date.now();
const actions = [];
for (const item of $input.all()) {
  const row = item.json;
  if (!row || !row.bookingId || !row.phone) continue;
  const startMs = Date.parse(String(row.startTimeIso || ''));
  if (!Number.isFinite(startMs) || startMs <= now) continue;
  const pollMs = Date.parse(String(row.pollDueAt || ''));
  const finalMs = Date.parse(String(row.finalReminderDueAt || ''));
  if (row.status === 'Scheduled' && row.pollSent !== 'Yes' && Number.isFinite(pollMs) && pollMs <= now) {
    actions.push({ json: { ...row, reminderAction: 'send_poll', brandName: cfg.brandName, spreadsheetId: cfg.spreadsheetId } });
  } else if ((row.status === 'Scheduled' || row.status === 'Confirmed') && row.finalReminderSent !== 'Yes' && Number.isFinite(finalMs) && finalMs <= now) {
    actions.push({ json: { ...row, reminderAction: 'send_final', brandName: cfg.brandName, spreadsheetId: cfg.spreadsheetId } });
  }
}
return actions;

const row = $input.first()?.json;
if (!row || !row.bookingId || row.status !== 'Scheduled') return [];
const ev = $('When Invitee Votes on Attendance Poll').first().json || {};
const cfg = $('Vote Handler Configuration').first().json || {};
const selected = ev.vote?.selectedOptionIndices;
if (!Array.isArray(selected) || selected.length === 0) return [];
const idx = Number(selected[0]);
if (idx < 0 || idx > 2) return [];
const choices = ['confirmed', 'reschedule', 'cancel'];
return [{
  json: {
    ...row,
    chatId: String(ev.chat?.id || row.phone),
    choice: choices[idx],
    brandName: cfg.brandName,
    spreadsheetId: cfg.spreadsheetId,
    slackHostChannelId: cfg.slackHostChannelId,
  },
}];
